#!/usr/bin/env node
/**
 * repair-overcut-highlight-metadata.js — bring `overcut` puzzle/candidate rows back in sync with
 * the spec-052 (Epic 2) detector.
 *
 * Why this exists (OI-92):
 *   Spec 052 US1 split `detectOvercut` into role-named functions and US2 added two new match
 *   branches (`minor_threat`, `active_forcing`). Rows generated by the OLD, narrower detector can
 *   now be stale in two distinct ways:
 *     1. STALE METADATA — the detector now matches an earlier column via a new mechanism, so the
 *        stored `highlight_metadata` names a different cell pair than the current code derives.
 *        This is player-facing: `evalOvercut` grades the answer against the STORED metadata
 *        (overcut rows carry no single correct column), so a player who plays the newly-valid
 *        column is marked wrong.
 *     2. AMBIGUOUS — the widened detector finds TWO structurally valid overcut columns, tripping
 *        `checkOvercutPredicate`'s singleton guard. The board was always ambiguous; the old
 *        detector simply could not see the second column. These are not repairable by rewriting
 *        metadata — they violate the unique-answer rule and must be retired.
 *
 * What it does:
 *   - REPAIR (default): UPDATE `highlight_metadata` (and `category_evidence`) in place for rows
 *     whose re-derived value differs but which still pass the predicate with exactly one column.
 *   - RETIRE (--retire): for ambiguous rows, set `puzzles.is_active = false` /
 *     `candidates.status = 'rejected'`. Off by default — retiring content is a product decision.
 *
 * Safety:
 *   - `--env` selects local | staging | production; there is no default. You must name the target.
 *   - Refuses to touch production unless `--i-understand-this-is-production` is also passed.
 *   - `--dry-run` is the default posture for anything destructive: you must pass `--apply` to write.
 *   - Requires typing `Yes` (exact) at an interactive prompt before any write, twice for production.
 *   - Never rewrites a row whose re-derived metadata is byte-identical (after JSONB key-order
 *     canonicalization — raw JSON.stringify false-flags every row on key order alone).
 *
 * Usage:
 *   node scripts/repair-overcut-highlight-metadata.js --env staging               # dry-run report
 *   node scripts/repair-overcut-highlight-metadata.js --env staging --apply
 *   node scripts/repair-overcut-highlight-metadata.js --env staging --apply --retire
 *   node scripts/repair-overcut-highlight-metadata.js --help
 *
 * See docs/deployment_steps.md § "Spec 052 — overcut pool repair" for the full runbook.
 */

import fs from 'fs';
import path from 'path';
import readline from 'readline';
import { fileURLToPath } from 'url';
import { createClient } from '@supabase/supabase-js';
import { createSolverProcess } from '../c4solver-wrapper.js';
import { checkOvercutPredicate } from '../candidate-generator.js';
import { Board, detectOvercutBeneficiary } from '../classifier.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const STAGING_REF = 'jkqilynpshutqcceopdn';
const PRODUCTION_REF = 'kxtqwsumojtexokrtlfp';

const ENVS = {
  local:      { file: '.env',            ref: null },
  staging:    { file: '.env.staging',    ref: STAGING_REF },
  production: { file: '.env.production', ref: PRODUCTION_REF },
};

function printHelp() {
  console.log(`
repair-overcut-highlight-metadata.js — re-derive stale \`overcut\` highlight_metadata (OI-92).

Spec 052 widened the overcut detector (new \`minor_threat\` / \`active_forcing\` branches). Rows
built by the old detector can name the wrong cells — and \`evalOvercut\` grades against the STORED
metadata, so those rows mark a correct answer wrong.

Options:
  --env NAME       REQUIRED. One of: local | staging | production. No default — name the target.
  --apply          Actually write. Without it, the script only reports (dry run).
  --retire         Also retire AMBIGUOUS rows (2+ valid columns): puzzles.is_active=false,
                   candidates.status='rejected'. Off by default — this is a product decision.
  --i-understand-this-is-production
                   Required in addition to --apply when --env production.
  --help, -h       Show this help and exit 0 without connecting to anything.

Exit codes: 0 = clean or repaired; 1 = error; 2 = drift found in dry-run (useful as a deploy gate).

Examples:
  node scripts/repair-overcut-highlight-metadata.js --env staging
  node scripts/repair-overcut-highlight-metadata.js --env staging --apply --retire
`);
}

// Parse .env manually — dotenv is not reliably available (see project memory).
function parseEnv(filePath) {
  const out = {};
  for (const line of fs.readFileSync(filePath, 'utf8').split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    let val = trimmed.slice(eq + 1).trim();
    if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1);
    }
    out[key] = val;
  }
  return out;
}

/**
 * Stable-key JSON so JSONB key-order drift does not false-flag every row as changed.
 * Postgres does not preserve object key order in jsonb; comparing raw JSON.stringify output
 * reports 100% "differing" rows. See memory project_lesson_answer_set_invariant.md.
 */
function canon(value) {
  return JSON.stringify(value, (_k, v) =>
    (v && typeof v === 'object' && !Array.isArray(v))
      ? Object.fromEntries(Object.keys(v).sort().map((k) => [k, v[k]]))
      : v);
}

function ask(question) {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  return new Promise((resolve) => rl.question(question, (a) => { rl.close(); resolve(a); }));
}

/** Classify one row against the CURRENT detector. Pure — performs no writes. */
async function inspectRow(row, solver) {
  const scores = await solver.query(row.move_string);
  const raw = detectOvercutBeneficiary(new Board(row.move_string), scores);
  const res = checkOvercutPredicate(row.move_string, scores);

  if (!res.passes) {
    // Distinguish "ambiguous" (2+ valid columns — retirable) from "no longer an overcut at all",
    // because the two need different remedies and conflating them would silently retire content
    // that is merely mis-shaped rather than ambiguous.
    const kind = (raw.correctCols?.length ?? 0) > 1 ? 'ambiguous' : 'no_longer_matches';
    return { kind, reason: raw.reason ?? null, cols: raw.correctCols ?? [] };
  }
  if (canon(res.highlight_metadata) === canon(row.highlight_metadata)) {
    return { kind: 'identical', reason: raw.reason ?? null };
  }
  return {
    kind: 'stale',
    reason: raw.reason ?? null,
    highlight_metadata: res.highlight_metadata,
    category_evidence: res.category_evidence,
  };
}

async function main() {
  const args = process.argv.slice(2);
  if (args.includes('--help') || args.includes('-h')) { printHelp(); process.exit(0); }

  const envName = args[args.indexOf('--env') + 1];
  if (!args.includes('--env') || !ENVS[envName]) {
    console.error('ERROR: --env is required and must be one of: local | staging | production');
    console.error('       Run with --help for usage.');
    process.exit(1);
  }
  const apply = args.includes('--apply');
  const retire = args.includes('--retire');
  const prodAck = args.includes('--i-understand-this-is-production');

  if (envName === 'production' && apply && !prodAck) {
    console.error('ABORT: --env production with --apply also requires --i-understand-this-is-production.');
    process.exit(1);
  }

  const envPath = path.join(__dirname, '..', ENVS[envName].file);
  if (!fs.existsSync(envPath)) {
    console.error(`ERROR: env file not found at ${envPath}`);
    process.exit(1);
  }
  const env = parseEnv(envPath);
  if (!env.SUPABASE_URL || !env.SUPABASE_SERVICE_ROLE_KEY) {
    console.error(`ERROR: SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY missing from ${ENVS[envName].file}`);
    process.exit(1);
  }

  // Guard: the env file's URL must actually match the environment the caller named. This catches
  // an edited/copied .env pointing somewhere unexpected — the failure mode that makes "I ran it
  // against staging" quietly false.
  const expectedRef = ENVS[envName].ref;
  if (expectedRef && !env.SUPABASE_URL.includes(expectedRef)) {
    console.error(`ABORT: --env ${envName} expects project ref ${expectedRef}, but ${ENVS[envName].file} points at ${env.SUPABASE_URL}`);
    process.exit(1);
  }
  if (envName !== 'production' && env.SUPABASE_URL.includes(PRODUCTION_REF)) {
    console.error(`ABORT: ${ENVS[envName].file} points at the PRODUCTION ref. Refusing.`);
    process.exit(1);
  }

  console.log(`Target: ${envName.toUpperCase()}  (${env.SUPABASE_URL})`);
  console.log(`Mode:   ${apply ? 'APPLY (will write)' : 'DRY RUN (no writes)'}${retire ? ' + RETIRE ambiguous' : ''}\n`);

  const sb = createClient(env.SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY);
  const solver = createSolverProcess();
  const plan = { stale: [], ambiguous: [], no_longer_matches: [], identical: 0 };

  try {
    for (const [table, activeFilter] of [['puzzles', 'is_active'], ['candidates', 'status']]) {
      const { data, error } = await sb
        .from(table)
        .select('id, move_string, highlight_metadata')
        .eq('category', 'overcut');
      if (error) { console.error(`QUERY ERROR on ${table}: ${error.message}`); process.exit(1); }

      for (const row of data) {
        const verdict = await inspectRow(row, solver);
        if (verdict.kind === 'identical') { plan.identical++; continue; }
        plan[verdict.kind].push({ table, activeFilter, row, verdict });
      }
    }

    // ── Report ────────────────────────────────────────────────────────────────
    console.log(`identical (no action):      ${plan.identical}`);
    console.log(`stale metadata (repair):    ${plan.stale.length}`);
    console.log(`ambiguous (retire):         ${plan.ambiguous.length}`);
    console.log(`no longer matches at all:   ${plan.no_longer_matches.length}\n`);

    for (const { table, row, verdict } of plan.stale) {
      console.log(`  [stale]      ${table}/${row.id}  ${row.move_string}  -> ${verdict.reason}`);
    }
    for (const { table, row, verdict } of plan.ambiguous) {
      console.log(`  [ambiguous]  ${table}/${row.id}  ${row.move_string}  cols=[${verdict.cols}] (${verdict.reason})`);
    }
    for (const { table, row } of plan.no_longer_matches) {
      console.log(`  [no-match]   ${table}/${row.id}  ${row.move_string}  — NEEDS A HUMAN, not repaired or retired`);
    }

    const drift = plan.stale.length + plan.ambiguous.length + plan.no_longer_matches.length;
    if (drift === 0) { console.log('\n✅ Pool is in sync with the current detector. Nothing to do.'); process.exit(0); }

    if (!apply) {
      console.log('\nDry run — nothing was written. Re-run with --apply to repair.');
      if (plan.ambiguous.length && !retire) {
        console.log('Ambiguous rows need --retire (a product decision) or manual triage.');
      }
      process.exit(2);
    }

    // ── Confirm ───────────────────────────────────────────────────────────────
    const writes = plan.stale.length + (retire ? plan.ambiguous.length : 0);
    if (writes === 0) { console.log('\nNothing to write with the current flags.'); process.exit(2); }
    const first = await ask(`\nWrite ${writes} row(s) to ${envName.toUpperCase()}? Type "Yes" to proceed: `);
    if (first !== 'Yes') { console.log('Aborted.'); process.exit(1); }
    if (envName === 'production') {
      const second = await ask('This is PRODUCTION. Type "Yes" again to confirm: ');
      if (second !== 'Yes') { console.log('Aborted.'); process.exit(1); }
    }

    // ── Apply ─────────────────────────────────────────────────────────────────
    let repaired = 0, retired = 0;
    for (const { table, row, verdict } of plan.stale) {
      const patch = { highlight_metadata: verdict.highlight_metadata };
      if (verdict.category_evidence !== undefined) patch.category_evidence = verdict.category_evidence;
      const { error } = await sb.from(table).update(patch).eq('id', row.id);
      if (error) { console.error(`  FAILED ${table}/${row.id}: ${error.message}`); continue; }
      repaired++;
    }
    if (retire) {
      for (const { table, row } of plan.ambiguous) {
        const patch = table === 'puzzles' ? { is_active: false } : { status: 'rejected' };
        const { error } = await sb.from(table).update(patch).eq('id', row.id);
        if (error) { console.error(`  FAILED ${table}/${row.id}: ${error.message}`); continue; }
        retired++;
      }
    }
    console.log(`\n✅ repaired ${repaired} row(s); retired ${retired} row(s).`);
    if (plan.no_longer_matches.length) {
      console.log(`⚠️  ${plan.no_longer_matches.length} row(s) no longer match the predicate at all and were left untouched — triage these by hand.`);
    }
    console.log('Re-run this script without --apply to confirm the pool is now clean.');
  } finally {
    solver.destroy?.();
  }
}

main().catch((err) => { console.error(err); process.exit(1); });
